package br.com.fintrack.service;
import br.com.fintrack.dto.TransacaoDTO; import br.com.fintrack.model.*; import br.com.fintrack.repository.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import java.math.BigDecimal; import java.time.LocalDate; import java.util.Optional; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class TransacaoServiceTest{
 @Mock TransacaoRepository transacoes; @Mock CategoriaRepository categorias; @Mock UsuarioRepository usuarios; @InjectMocks TransacaoService service;
 @Test void devePermitirDespesaMaiorQueSaldo(){Usuario usuario=new Usuario("Teste","teste@email.com","senha");Categoria categoria=new Categoria("Compras","#123456",usuario);when(usuarios.findById(1L)).thenReturn(Optional.of(usuario));when(categorias.findByIdAndUsuarioId(2L,1L)).thenReturn(Optional.of(categoria));when(transacoes.save(any(Transacao.class))).thenAnswer(invocacao->invocacao.getArgument(0));TransacaoDTO dto=new TransacaoDTO(null,LocalDate.now(),"Compra",new BigDecimal("900.00"),TipoTransacao.DESPESA,"",false,2L,null);TransacaoDTO criada=service.criar(1L,dto);assertEquals(new BigDecimal("900.00"),criada.valor());assertEquals(TipoTransacao.DESPESA,criada.tipo());verify(transacoes).save(any(Transacao.class));verify(transacoes,never()).sumValorByUsuarioIdAndTipo(anyLong(),any());}
 @Test void deveCalcularSaldoDoPeriodo(){LocalDate i=LocalDate.of(2026,1,1),f=LocalDate.of(2026,12,31);when(transacoes.sumValorPeriodo(1L,TipoTransacao.RECEITA,i,f)).thenReturn(new BigDecimal("500.00"));when(transacoes.sumValorPeriodo(1L,TipoTransacao.DESPESA,i,f)).thenReturn(new BigDecimal("125.00"));assertEquals(new BigDecimal("375.00"),service.saldo(1L,i,f).saldo());}
}
